// Obtener respuesta del agente
const response = items[0].json.output;

// Extraer SQL del bloque de código
const sqlMatch = response.match(/```sql\s*([\s\S]*?)\s*```/);

if (!sqlMatch) {
  return [{
    json: {
      error: true,
      mensaje: "No se pudo extraer el SQL del response",
      response_raw: response
    }
  }];
}

const sql = sqlMatch[1].trim();

// Validación de seguridad básica
const sqlLower = sql.toLowerCase();
const operacionesProhibidas = ['drop', 'delete', 'truncate', 'update', 'insert', 'alter', 'create'];
const tieneOperacionProhibida = operacionesProhibidas.some(op => 
  sqlLower.includes(` ${op} `) || sqlLower.startsWith(op + ' ')
);

if (tieneOperacionProhibida) {
  return [{
    json: {
      error: true,
      mensaje: "El SQL contiene operaciones prohibidas (solo SELECT permitido)",
      sql_generado: sql
    }
  }];
}

// Devolver SQL limpio
return [{
  json: {
    sql_query: sql
  }
}];

// Junta los resultados SIN imagen en un solo mensaje de texto.
const items = $input.all();

const sinFoto = items.filter(function (i) {
  const tieneFoto = Boolean(i.json.foto_url);
  return (i.json.sin_resultados !== true) && !tieneFoto;
});

const resumen = sinFoto.map(function (i) {
  const cod  = (i.json.Codigo != null) ? i.json.Codigo : '';
  const nom  = (i.json['Nombre artículo'] != null) ? i.json['Nombre artículo'] : '';
  const desc = (i.json['Descripción'] != null) ? String(i.json['Descripción']).trim() : '';
  const obs  = (i.json.observaciones != null) ? String(i.json.observaciones).trim() : '';
  let bloque = 'Codigo: ' + cod + '\nNombre: ' + nom;
  if (desc) { bloque += '\nDescripción: ' + desc; }
  if (obs)  { bloque += '\nObservaciones: ' + obs; }
  return bloque;
}).join('\n\n');

return [{ json: { resumen: resumen, tiene_resumen: sinFoto.length > 0 } }];

// Devuelve, uno por item, solo los resultados con foto en Supabase Storage.
const all = $('Sumar fotos de Storage').all();

const conFoto = all.filter(function (i) {
  return (i.json.sin_resultados !== true) && i.json.foto_url;
});

return conFoto;

// Obtener el item de entrada
const item = $input.first().json;

// Variable para almacenar el texto resultante
let texto = null;

// Verificar en orden de prioridad cuál variable existe y tiene contenido
if (item.message && item.message.text) {
  texto = item.message.text;
} else if (item.text) {
  texto = item.text;
} else if (item.content) {
  texto = item.content;
}

// Retornar el resultado
return {
  json: {
    texto: texto,
    // Opcional: incluir información sobre qué variable se usó
    fuente: item.message?.text ? 'message.text' : 
            item.text ? 'text' : 
            item.content ? 'content' : 'ninguna'
  }
};

// Le suma a cada resultado del SQL el link público de su foto en Supabase Storage.
const BASE = 'https://<PROJECT_REF>.supabase.co/storage/v1/object/public/fotos/';
const fotos = {};
for (const f of $('Buscar fotos en Storage').all()) {
  if (f.json.codigo && f.json.foto) fotos[f.json.codigo] = f.json.foto;
}
return $('Execute a SQL query1').all().map(function (i) {
  const foto = fotos[String(i.json.Codigo ?? '').trim()];
  return { json: Object.assign({}, i.json, { foto_url: foto ? BASE + foto : null }) };
});
